fn two_sum(nums: Vec<i32>, target: i32) -> Option<(usize, usize)> {
    let n = nums.len();
    for i in 0..n {
        for j in i + 1..n {
            // Use checked_add to ignore pairs that would overflow i32
            if let Some(sum) = nums[i].checked_add(nums[j]) {
                if sum == target {
                    return Some((i, j));
                }
            }
        }
    }
    None
}

